const chettinadData={thinnai:{title:"Thinnai (Veranda)",description:"The 'Thinnai' is an elevated open veranda at the entrance of the house. It served as a social space where the men of the house would receive guests, conduct business, and travelers could rest. It features beautifully carved wooden pillars and a sloped roof.",materials:"Burma Teak wood for pillars and intricate carvings; brick and lime mortar for the raised platform.",ventilation:"Completely open to the street, allowing the evening breeze to cool the house entrance.",trade:"The use of imported Burma Teak highlights the prosperous timber trade the Nattukottai Chettiars established in Southeast Asia."},mugappu:{title:"Mugappu (Reception)",description:"The 'Mugappu' is the grand reception hall that leads into the first courtyard. It is often ornately decorated with rich woodwork, stucco work on the ceilings, and massive wooden doors heavily fortified with brass knobs.",materials:"Heavy Burma Teak doors, intricately carved frames, and Stucco detailing.",ventilation:"Acts as a transitional buffer zone between the bright, hot street and the cooler interior.",trade:"Features imported brass and glass fixtures from Europe, showcasing their global trade connections."},mutram:{title:"Mutram (Main Courtyard)",description:"The 'Mutram' is the heart of a Chettinad home—a large, open-to-sky courtyard. It was the primary gathering space for the family, used for daily activities, drying spices, and harvesting rainwater.",materials:"Vibrant, handmade Athangudi tiles on the floor; granite pillars supporting the surrounding corridors; terracotta roof tiles.",ventilation:"The open-to-sky design (sunken courtyard) acts as a thermal chimney, drawing hot air out and creating constant cross-ventilation throughout the massive mansion.",trade:"Athangudi tiles were initially inspired by European floor tiles, later localized by artisans in the Chettinad region using local soil and glass plates."},kalyana:{title:"Kalyana Kottagai (Hall)",description:"A magnificent, expansive hall used specifically for weddings and large family ceremonies. These halls can accommodate hundreds of guests and feature the most elaborate architecture in the entire house.",materials:"Italian marble flooring, Belgian glass mirrors, and Czechoslovakian chandeliers.",ventilation:"High ceilings and alignment with the courtyards ensure natural airflow even during crowded events.",trade:"A stunning display of wealth, heavily utilizing imported European luxury goods from their global trade networks."},irandaam:{title:"Irandaam Kattu (Second Courtyard)",description:"The 'Irandaam Kattu' is the second courtyard, designed as a private space for the women of the household. It is surrounded by smaller rooms used for storage, dining, and daily household chores.",materials:"Local brick and lime mortar (karai), wooden pillars, and red oxide flooring.",ventilation:"Works in tandem with the first courtyard to create a wind tunnel effect, cooling the deep interior of the house.",trade:"Storage rooms often held spices, paddy, and goods traded from across the Bay of Bengal."},kitchen:{title:"Aduppadi (Kitchen & Backyard)",description:"Located at the very back of the deep rectangular plot, the kitchen area was massive, designed to cook for extended families and large feasts. It often opened up to a backyard with a well.",materials:"Traditional mud stoves, heavy brass and copper vessels, and stone grinders (Ammi and Ural).",ventilation:"Positioned at the rear to ensure smoke from the wood-fired stoves exited away from the main living areas.",trade:"The presence of massive storage bins for exotic spices from Ceylon, Malaya, and Indonesia."}};document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".fp-section"),t=document.getElementById("section-title"),a=document.getElementById("section-description"),i=document.getElementById("section-meta"),o=document.getElementById("meta-materials"),n=document.getElementById("meta-ventilation"),r=document.getElementById("meta-trade");e.forEach(s=>{s.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),s.classList.add("active");const d=s.getAttribute("data-section"),l=chettinadData[d];l&&(t.textContent=l.title,a.textContent=l.description,o.textContent=l.materials,n.textContent=l.ventilation,r.textContent=l.trade,i.classList.remove("hidden"))})})});